## Как это работает

- **Отсчёт времени ведёт iOS, а не приложение.** На старте сессии система получает расписание «с этой минуты на 30 минут». Когда время выходит, iOS сама запускает ваше расширение DeviceActivityMonitor, даже если приложение в фоне или выгружено. Расширение снимает блокировку, засчитывает минуты и оставляет для Slumpy пометку «сказать при открытии».
- **Live Activity переключается сама.** На ней идёт системный обратный отсчёт. Ей заранее задано время окончания (`staleDate`), и в этот момент она сама показывает «Сессия окончена». Удаляет её приложение при следующем открытии.
- **Запасной путь.** При каждом открытии приложение проверяет, не закончилась ли сессия, и если расширение почему-то не сработало, завершает её само. Если приложение открыто в момент окончания, сессия завершается сразу.
- **Минуты не засчитаются дважды.** Приложение и расширение работают с одним общим файлом в App Group и по очереди его блокируют. Каждая сессия закрывается ровно один раз.

## 1. `Shared/ReadingSessionShared.swift`
Добавить в таргеты: **приложение + расширение DeviceActivityMonitor**.

```swift
import DeviceActivity
import Foundation
import ManagedSettings

enum AppGroup {
    // Replace with the App Group identifier from Signing & Capabilities.
    static let id = "group.com.example.slumpy"
}

extension ManagedSettingsStore.Name {
    static var readingSession: Self { Self("readingSession") }
}

struct ReadingSession: Codable, Equatable, Sendable {
    let id: UUID
    let startDate: Date
    let endDate: Date
    /// Fixed at start so a session crossing midnight is credited to the day it began.
    let dayKey: String

    var minutes: Int { Int((endDate.timeIntervalSince(startDate) / 60).rounded()) }

    private static let activityPrefix = "readingSession."

    static func activityName(for id: UUID) -> DeviceActivityName {
        DeviceActivityName(activityPrefix + id.uuidString)
    }

    static func sessionID(from activity: DeviceActivityName) -> UUID? {
        guard activity.rawValue.hasPrefix(activityPrefix) else { return nil }
        return UUID(uuidString: String(activity.rawValue.dropFirst(activityPrefix.count)))
    }

    var activityName: DeviceActivityName { Self.activityName(for: id) }

    var schedule: DeviceActivitySchedule {
        let components: Set<Calendar.Component> = [.year, .month, .day, .hour, .minute, .second]
        return DeviceActivitySchedule(
            intervalStart: Calendar.current.dateComponents(components, from: startDate),
            intervalEnd: Calendar.current.dateComponents(components, from: endDate),
            repeats: false
        )
    }

    static func dayKey(for date: Date) -> String {
        let c = Calendar.current.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0)
    }
}

struct SharedState: Codable, Sendable {
    var activeSession: ReadingSession?
    var minutesByDay: [String: Int] = [:]
    var hasPendingEndMessage = false
}

/// State shared by the app and the monitor extension. A file lock instead of UserDefaults
/// because both processes do read-modify-write and must never credit a session twice.
enum SharedStateFile {
    private static var directory: URL {
        guard let url = FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: AppGroup.id) else {
            fatalError("App Group \(AppGroup.id) is not configured for this target")
        }
        return url
    }
    private static var fileURL: URL { directory.appending(path: "reading-session-state.json") }
    private static var lockURL: URL { directory.appending(path: "reading-session-state.lock") }

    static func read() -> SharedState? {
        withLock { load() }
    }

    /// Returns nil without writing anything if the existing file couldn't be read.
    @discardableResult
    static func update<T>(_ body: (inout SharedState) -> T) -> T? {
        withLock {
            guard var state = load() else { return nil }
            let result = body(&state)
            save(state)
            return result
        }
    }

    /// nil means the file exists but is unreadable; it must not be overwritten with empty state.
    private static func load() -> SharedState? {
        let data: Data
        do {
            data = try Data(contentsOf: fileURL)
        } catch CocoaError.fileReadNoSuchFile {
            return SharedState()
        } catch {
            return nil
        }
        return try? JSONDecoder().decode(SharedState.self, from: data)
    }

    private static func save(_ state: SharedState) {
        guard let data = try? JSONEncoder().encode(state) else { return }
        try? data.write(to: fileURL, options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])
    }

    private static func withLock<T>(_ body: () -> T) -> T {
        let fd = open(lockURL.path, O_CREAT | O_RDWR, 0o600)
        guard fd >= 0 else { return body() }
        defer { close(fd) } // Closing the descriptor releases the lock.
        flock(fd, LOCK_EX)
        return body()
    }
}

enum ReadingSessionFinalizer {
    /// Called by the monitor extension. No clock check: the system may fire slightly before the exact second.
    static func finalize(sessionID: UUID) {
        let readable = SharedStateFile.update { state in
            if state.activeSession?.id == sessionID { complete(&state) }
        }
        // Unblock even if the state file is unreadable: stuck apps are worse than an uncredited session.
        if readable == nil { stopBlocking(ReadingSession.activityName(for: sessionID)) }
    }

    /// Called by the app on launch/foreground in case the extension didn't run.
    static func finalizeIfDue(now: Date = .now) {
        SharedStateFile.update { state in
            if let session = state.activeSession, session.endDate <= now { complete(&state) }
        }
    }

    private static func complete(_ state: inout SharedState) {
        guard let session = state.activeSession else { return }
        // Unblock before saving: if the process dies in between, the session stays active and is retried.
        stopBlocking(session.activityName)
        state.activeSession = nil
        state.minutesByDay[session.dayKey, default: 0] += session.minutes
        state.hasPendingEndMessage = true
    }

    private static func stopBlocking(_ activity: DeviceActivityName) {
        ManagedSettingsStore(named: .readingSession).clearAllSettings()
        DeviceActivityCenter().stopMonitoring([activity])
    }
}
```

