## 3. `App/ReadingSessionManager.swift`
Таргет: **приложение**.

```swift
import ActivityKit
import DeviceActivity
import FamilyControls
import Foundation
import ManagedSettings
import Observation

@MainActor
@Observable
final class ReadingSessionManager {
    static let endMessage = "Сессия окончена"

    private(set) var activeSession: ReadingSession?
    private(set) var todayMinutes = 0
    private(set) var slumpyMessage: String?

    @ObservationIgnored private var completionCheck: Task<Void, Never>?

    init() {
        refresh()
    }

    /// iOS only monitors intervals of 15 minutes or longer; shorter sessions make startMonitoring throw.
    func start(minutes: Int = 30, blocking selection: FamilyActivitySelection) throws {
        refresh()
        guard activeSession == nil else { return }

        let now = Date.now
        let session = ReadingSession(
            id: UUID(),
            startDate: now,
            endDate: now.addingTimeInterval(TimeInterval(minutes * 60)),
            dayKey: ReadingSession.dayKey(for: now)
        )
        // The extension ends the session on time even if the app is suspended or terminated.
        try DeviceActivityCenter().startMonitoring(session.activityName, during: session.schedule)
        guard SharedStateFile.update({ $0.activeSession = session }) != nil else {
            DeviceActivityCenter().stopMonitoring([session.activityName])
            throw CocoaError(.fileReadUnknown)
        }

        let store = ManagedSettingsStore(named: .readingSession)
        let categories = selection.categoryTokens
        store.shield.applications = selection.applicationTokens.isEmpty ? nil : selection.applicationTokens
        store.shield.applicationCategories = categories.isEmpty ? nil : .specific(categories)
        store.shield.webDomains = selection.webDomainTokens.isEmpty ? nil : selection.webDomainTokens
        store.shield.webDomainCategories = categories.isEmpty ? nil : .specific(categories)

        startLiveActivity(for: session)
        activeSession = session
        scheduleCompletionCheck()
    }

    /// Call on launch and whenever the app becomes active.
    func refresh() {
        ReadingSessionFinalizer.finalizeIfDue()
        guard let state = SharedStateFile.read() else { return }

        activeSession = state.activeSession
        todayMinutes = state.minutesByDay[ReadingSession.dayKey(for: .now)] ?? 0
        if state.hasPendingEndMessage {
            slumpyMessage = Self.endMessage
        }
        endLiveActivities(except: state.activeSession?.id)
        scheduleCompletionCheck()
    }

    /// Call after Slumpy has said the message; the flag survives until then, even across app kills.
    func dismissSlumpyMessage() {
        slumpyMessage = nil
        SharedStateFile.update { $0.hasPendingEndMessage = false }
    }

    private func startLiveActivity(for session: ReadingSession) {
        guard ActivityAuthorizationInfo().areActivitiesEnabled else { return }
        let attributes = ReadingSessionAttributes(
            sessionID: session.id,
            startDate: session.startDate,
            endDate: session.endDate
        )
        // staleDate lets the widget switch to "finished" at the end time without the app running.
        let content = ActivityContent(
            state: ReadingSessionAttributes.ContentState(isFinished: false),
            staleDate: session.endDate
        )
        // The session works without a Live Activity, so a failure here is not surfaced.
        _ = try? Activity.request(attributes: attributes, content: content)
    }

    private func endLiveActivities(except activeID: UUID?) {
        for activity in Activity<ReadingSessionAttributes>.activities where activity.attributes.sessionID != activeID {
            Task {
                await activity.end(
                    ActivityContent(state: .init(isFinished: true), staleDate: nil),
                    dismissalPolicy: .immediate
                )
            }
        }
    }

    /// While the app stays in the foreground, finish the session right at its end time.
    private func scheduleCompletionCheck() {
        completionCheck?.cancel()
        guard let endDate = activeSession?.endDate else { return }
        completionCheck = Task { [weak self] in
            try? await Task.sleep(for: .seconds(max(endDate.timeIntervalSinceNow, 0) + 1))
            guard !Task.isCancelled else { return }
            self?.refresh()
        }
    }
}
```

