Если в расширении уже есть свой класс, перенесите тело `intervalDidEnd` в него. Если такой метод там уже есть, добавьте в него две строки после `super`.

```swift
import DeviceActivity
import Foundation

final class ReadingSessionMonitor: DeviceActivityMonitor {
    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        guard let sessionID = ReadingSession.sessionID(from: activity) else { return }
        ReadingSessionFinalizer.finalize(sessionID: sessionID)
    }
}
```

