### 1. `ReadingSessionShared.swift`: в цели **приложения и DeviceActivityMonitor**

```swift
import DeviceActivity
import Foundation
import ManagedSettings

enum ReadingSessionConfig {
    // Replace with the App Group identifier already configured for the app and the extension.
    static let appGroupID = "group.com.example.slumpy"
    static let endMessage = "Сессия окончена"
}

struct ReadingSession: Codable, Equatable, Sendable {
    let id: UUID
    let startDate: Date
    let endDate: Date

    var minutes: Int { Int((endDate.timeIntervalSince(startDate) / 60).rounded()) }
}

struct ReadingSessionState: Codable, Sendable {
    var activeSession: ReadingSession?
    var minutesByDay: [String: Int] = [:]
    var pendingEndAnnouncement = false
}

extension ManagedSettingsStore.Name {
    static var readingSession: Self { Self("readingSession") }
}

/// Shared state lives in one JSON file in the App Group. The app and the monitor extension run in
/// separate processes and may finish the same session at the same moment, so every
/// read-modify-write happens under an exclusive file lock.
enum ReadingSessionStore {
    static func load() throws -> ReadingSessionState {
        try withLock { try read() }
    }

    @discardableResult
    static func update<T>(_ change: (inout ReadingSessionState) throws -> T) throws -> T {
        try withLock {
            var state = try read()
            let result = try change(&state)
            try write(state)
            return result
        }
    }

    static func dayKey(for date: Date) -> String {
        let parts = Calendar.current.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", parts.year ?? 0, parts.month ?? 0, parts.day ?? 0)
    }

    private static var containerURL: URL {
        guard let url = FileManager.default.containerURL(
            forSecurityApplicationGroupIdentifier: ReadingSessionConfig.appGroupID
        ) else {
            fatalError("App Group \(ReadingSessionConfig.appGroupID) is not enabled for this target")
        }
        return url
    }

    private static var stateURL: URL { containerURL.appending(path: "reading-session.json") }
    private static var lockURL: URL { containerURL.appending(path: "reading-session.lock") }

    // A missing file means "nothing stored yet"; an unreadable file (e.g. the phone restarted and
    // has not been unlocked) must throw, otherwise the next write would erase credited minutes.
    private static func read() throws -> ReadingSessionState {
        guard FileManager.default.fileExists(atPath: stateURL.path) else { return ReadingSessionState() }
        return try JSONDecoder().decode(ReadingSessionState.self, from: Data(contentsOf: stateURL))
    }

    // The extension usually runs while the phone is locked, so the file must stay readable then.
    private static func write(_ state: ReadingSessionState) throws {
        try JSONEncoder().encode(state).write(
            to: stateURL,
            options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication]
        )
    }

    private static func withLock<T>(_ body: () throws -> T) throws -> T {
        let descriptor = open(lockURL.path, O_CREAT | O_RDWR, 0o600)
        guard descriptor >= 0 else { throw POSIXError(POSIXErrorCode(rawValue: errno) ?? .EIO) }
        defer { close(descriptor) }
        flock(descriptor, LOCK_EX)
        return try body()
    }
}

/// The activity name carries the session id and end time, so the extension can ignore callbacks
/// from older sessions and still unblock on time when the shared file is unreadable.
enum ReadingSessionSchedule {
    private static let namePrefix = "reading-session."

    static func parse(_ activity: DeviceActivityName) -> (sessionID: UUID, endDate: Date)? {
        guard activity.rawValue.hasPrefix(namePrefix) else { return nil }
        let parts = activity.rawValue.dropFirst(namePrefix.count).split(separator: ".")
        guard parts.count == 2,
              let id = UUID(uuidString: String(parts[0])),
              let end = TimeInterval(parts[1])
        else { return nil }
        return (id, Date(timeIntervalSince1970: end))
    }

    /// DeviceActivity wakes the monitor extension at the end time even when the app is suspended
    /// or terminated. iOS rejects intervals shorter than 15 minutes.
    static func startMonitoring(_ session: ReadingSession) throws {
        let center = DeviceActivityCenter()
        let previous = center.activities.filter { parse($0) != nil }
        // An empty array would stop every schedule the app has, not just reading sessions.
        if !previous.isEmpty { center.stopMonitoring(previous) }

        let parts: Set<Calendar.Component> = [.hour, .minute, .second]
        let schedule = DeviceActivitySchedule(
            intervalStart: Calendar.current.dateComponents(parts, from: session.startDate),
            intervalEnd: Calendar.current.dateComponents(parts, from: session.endDate),
            repeats: false
        )
        let name = "\(namePrefix)\(session.id.uuidString).\(Int(session.endDate.timeIntervalSince1970))"
        try center.startMonitoring(DeviceActivityName(name), during: schedule)
    }
}

enum ReadingSessionFinisher {
    /// Ends the active session if its time is up: unblocks apps, credits minutes to the day the
    /// session started, and leaves a flag for Slumpy. Safe to call repeatedly from both processes.
    static func finishIfDue(sessionID: UUID? = nil, now: Date = .now) throws {
        try ReadingSessionStore.update { state in
            guard let session = state.activeSession,
                  sessionID == nil || sessionID == session.id,
                  now >= session.endDate
            else { return }
            ManagedSettingsStore(named: .readingSession).clearAllSettings()
            state.minutesByDay[ReadingSessionStore.dayKey(for: session.startDate), default: 0] += session.minutes
            state.activeSession = nil
            state.pendingEndAnnouncement = true
        }
    }
}
```

