### 3. `ReadingSessionController.swift`: только в цели **приложения**

```swift
import ActivityKit
import FamilyControls
import ManagedSettings
import Observation
import SwiftUI

@MainActor
@Observable
final class ReadingSessionController {
    private(set) var activeSession: ReadingSession?
    private(set) var todayMinutes = 0
    var slumpyMessage: String?

    private var endCheck: Task<Void, Never>?

    func start(minutes: Int = 30, blocking selection: FamilyActivitySelection) throws {
        guard activeSession == nil else { return }
        let now = Date.now
        let session = ReadingSession(
            id: UUID(),
            startDate: now,
            endDate: now.addingTimeInterval(TimeInterval(minutes * 60))
        )

        try ReadingSessionStore.update { $0.activeSession = session }
        do {
            try ReadingSessionSchedule.startMonitoring(session)
        } catch {
            try? ReadingSessionStore.update { $0.activeSession = nil }
            throw error
        }

        let store = ManagedSettingsStore(named: .readingSession)
        store.shield.applications = selection.applicationTokens.isEmpty ? nil : selection.applicationTokens
        store.shield.applicationCategories = selection.categoryTokens.isEmpty ? nil : .specific(selection.categoryTokens)
        store.shield.webDomains = selection.webDomainTokens.isEmpty ? nil : selection.webDomainTokens

        // Live Activities are optional: the user may have turned them off in Settings.
        // staleDate makes iOS switch the widget to "Сессия окончена" on time without the app.
        _ = try? Activity<ReadingSessionAttributes>.request(
            attributes: ReadingSessionAttributes(startDate: session.startDate, endDate: session.endDate),
            content: ActivityContent(state: ReadingSessionAttributes.ContentState(), staleDate: session.endDate)
        )

        activeSession = session
        scheduleEndCheck()
    }

    /// Called whenever the app becomes active: finishes a session whose time ran out while the app
    /// was suspended or terminated, removes finished Live Activities, and delivers Slumpy's line.
    func refresh() {
        // On failure the session stays active and the next refresh retries.
        try? ReadingSessionFinisher.finishIfDue()
        Task { await endFinishedLiveActivities() }
        guard let state = try? ReadingSessionStore.load() else { return }

        activeSession = state.activeSession
        todayMinutes = state.minutesByDay[ReadingSessionStore.dayKey(for: .now)] ?? 0
        if state.pendingEndAnnouncement {
            slumpyMessage = ReadingSessionConfig.endMessage
            try? ReadingSessionStore.update { $0.pendingEndAnnouncement = false }
        }
        scheduleEndCheck()
    }

    // Only matters while the app is in the foreground; otherwise the monitor extension or the
    // next refresh() finishes the session.
    private func scheduleEndCheck() {
        endCheck?.cancel()
        guard let endDate = activeSession?.endDate else { return }
        endCheck = Task { [weak self] in
            try? await Task.sleep(for: .seconds(max(0, endDate.timeIntervalSinceNow)))
            guard !Task.isCancelled else { return }
            self?.refresh()
        }
    }

    private func endFinishedLiveActivities() async {
        for activity in Activity<ReadingSessionAttributes>.activities where activity.attributes.endDate <= .now {
            await activity.end(nil, dismissalPolicy: .immediate)
        }
    }
}

extension View {
    /// Attach once to the root view of the app.
    func readingSessionHost(_ controller: ReadingSessionController) -> some View {
        modifier(ReadingSessionHost(controller: controller))
    }
}

private struct ReadingSessionHost: ViewModifier {
    @Environment(\.scenePhase) private var scenePhase
    let controller: ReadingSessionController

    func body(content: Content) -> some View {
        content
            .onChange(of: scenePhase, initial: true) { _, phase in
                if phase == .active { controller.refresh() }
            }
            .overlay(alignment: .bottom) {
                if let message = controller.slumpyMessage {
                    // Replace with Slumpy's own speech component if the app has one.
                    Text(message)
                        .font(.headline)
                        .padding()
                        .background(.regularMaterial, in: .rect(cornerRadius: 16))
                        .padding()
                        .onTapGesture { controller.slumpyMessage = nil }
                }
            }
    }
}
