### 4. `DeviceActivityMonitorExtension.swift`: цель **DeviceActivityMonitor**

Если в расширении уже есть свой класс, перенесите в него метод `intervalDidEnd`.

```swift
import DeviceActivity
import Foundation
import ManagedSettings

class DeviceActivityMonitorExtension: DeviceActivityMonitor {
    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        guard let scheduled = ReadingSessionSchedule.parse(activity) else { return }

        // The schedule may fire slightly before the end time because of minute rounding.
        let now = Date.now.addingTimeInterval(60)
        do {
            try ReadingSessionFinisher.finishIfDue(sessionID: scheduled.sessionID, now: now)
        } catch {
            // Shared state is unreadable (e.g. the phone restarted and is still locked).
            // Unblock on time anyway; the app credits the minutes on its next launch.
            if now >= scheduled.endDate {
                ManagedSettingsStore(named: .readingSession).clearAllSettings()
            }
        }
    }
}
```

