import ActivityKit
import SwiftUI
import WidgetKit

struct ReadingSessionLiveActivity: Widget {
    var body: some WidgetConfiguration {
        ActivityConfiguration(for: ReadingSessionAttributes.self) { context in
            ReadingSessionStatus(context: context)
                .padding()
        } dynamicIsland: { context in
            DynamicIsland {
                DynamicIslandExpandedRegion(.bottom) {
                    ReadingSessionStatus(context: context)
                }
            } compactLeading: {
                Image(systemName: "book.fill")
            } compactTrailing: {
                if context.isStale {
                    Image(systemName: "checkmark")
                } else {
                    Text(timerInterval: context.attributes.startDate...context.attributes.endDate, countsDown: true)
                        .monospacedDigit()
                        .frame(maxWidth: 44)
                }
            } minimal: {
                Image(systemName: "book.fill")
            }
        }
    }
}

// After staleDate (the session end) iOS marks the activity stale and redraws it. That is the only
// way to change it on time while the app is not running; the app removes it on its next launch.
private struct ReadingSessionStatus: View {
    let context: ActivityViewContext<ReadingSessionAttributes>

    var body: some View {
        if context.isStale {
            Label("Сессия окончена", systemImage: "checkmark.circle.fill")
        } else {
            HStack {
                Label("Чтение", systemImage: "book.fill")
                Spacer()
                Text(timerInterval: context.attributes.startDate...context.attributes.endDate, countsDown: true)
                    .font(.title2.monospacedDigit())
            }
        }
    }
}
